{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Application filter list panel (multi-select) with dashboard filter integration.",
  "autosize": "fit",
  "padding": 10,
  "background": "#000000",
  "signals": [
    {
      "name": "selectedApps",
      "value": "|",
      "on": [
        {
          "events": "@appRowBg:click",
          "update": "indexof(selectedApps, '|' + datum.app + '|') >= 0 ? replace(selectedApps, '|' + datum.app + '|', '|') : selectedApps + datum.app + '|'"
        }
      ]
    },
    {
      "name": "selectedAppsArray",
      "update": "selectedApps == '|' ? [] : split(slice(selectedApps, 1, length(selectedApps)-1), '|')"
    },
    {
      "name": "activeFilter",
      "update": "length(selectedAppsArray) > 0 ? {'bool': {'filter': [{'term': {'event.dataset': 'tychon.application'}}, {'terms': {'tychon.application.name': selectedAppsArray}}]}} : {'term': {'event.dataset': 'tychon.application'}}"
    },
    {
      "name": "_applyAppFilter",
      "value": 0,
      "on": [
        {
          "events": "@applyBtn:click",
          "update": "kibanaAddFilter(activeFilter)",
          "force": true
        }
      ]
    }
  ],
  "data": [
    {
      "name": "apps",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc-applications",
        "body": {
          "size": 0,
          "aggs": {
            "app_only": {
              "filter": { "term": { "event.dataset": "tychon.application" } },
              "aggs": {
                "app_names": {
                  "terms": {
                    "field": "tychon.application.name",
                    "size": 200,
                    "order": { "_count": "desc" }
                  }
                }
              }
            }
          }
        }
      },
      "format": { "property": "aggregations.app_only.app_names.buckets" },
      "transform": [
        { "type": "formula", "as": "app", "expr": "datum.key" },
        { "type": "formula", "as": "count", "expr": "datum.doc_count" },
        { "type": "window", "ops": ["row_number"], "as": ["rn"] },
        { "type": "formula", "as": "y", "expr": "72 + (datum.rn - 1) * 26" },
        { "type": "filter", "expr": "datum.rn <= 15" }
      ]
    }
  ],
  "marks": [
    {
      "type": "rect",
      "encode": {
        "update": {
          "x": { "value": 10 },
          "y": { "value": 10 },
          "x2": { "signal": "width - 10" },
          "y2": { "signal": "height - 10" },
          "fill": { "value": "#0f1115" },
          "fillOpacity": { "value": 0.96 },
          "stroke": { "value": "#2b3440" },
          "strokeWidth": { "value": 1.2 },
          "cornerRadius": { "value": 8 }
        }
      }
    },
    {
      "type": "rect",
      "encode": {
        "update": {
          "x": { "value": 10 },
          "y": { "value": 10 },
          "x2": { "signal": "width - 10" },
          "y2": { "value": 42 },
          "fill": { "value": "#17324a" },
          "fillOpacity": { "value": 0.92 },
          "cornerRadiusTopLeft": { "value": 8 },
          "cornerRadiusTopRight": { "value": 8 }
        }
      }
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": { "value": 24 },
          "y": { "value": 30 },
          "text": { "value": "APPLICATION FILTER" },
          "font": { "value": "monospace" },
          "fontSize": { "value": 12 },
          "fontWeight": { "value": "bold" },
          "fill": { "value": "#e8f3ff" },
          "baseline": { "value": "middle" }
        }
      }
    },
    {
      "type": "rect",
      "name": "applyBtn",
      "encode": {
        "update": {
          "x": { "signal": "width - 92" },
          "y": { "value": 16 },
          "width": { "value": 76 },
          "height": { "value": 20 },
          "cornerRadius": { "value": 10 },
          "fill": { "value": "#17324a" },
          "stroke": { "value": "#9fd7ff" },
          "strokeWidth": { "value": 1 },
          "cursor": { "value": "pointer" }
        }
      }
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": { "signal": "width - 54" },
          "y": { "value": 26 },
          "text": { "value": "APPLY" },
          "font": { "value": "monospace" },
          "fontSize": { "value": 10 },
          "fontWeight": { "value": "bold" },
          "fill": { "value": "#dff0ff" },
          "align": { "value": "center" },
          "baseline": { "value": "middle" }
        }
      }
    },
    {
      "type": "rect",
      "from": { "data": "apps" },
      "name": "appRowBg",
      "encode": {
        "update": {
          "x": { "value": 18 },
          "y": { "signal": "datum.y - 10" },
          "x2": { "signal": "width - 18" },
          "y2": { "signal": "datum.y + 10" },
          "cornerRadius": { "value": 6 },
          "fill": { "signal": "indexof(selectedApps, '|' + datum.app + '|') >= 0 ? '#1f4d74' : '#0f1115'" },
          "stroke": { "signal": "indexof(selectedApps, '|' + datum.app + '|') >= 0 ? '#9fd7ff' : '#253241'" },
          "strokeWidth": { "value": 1 },
          "cursor": { "value": "pointer" }
        }
      }
    },
    {
      "type": "text",
      "from": { "data": "apps" },
      "encode": {
        "update": {
          "x": { "value": 30 },
          "y": { "field": "y" },
          "text": { "field": "app" },
          "font": { "value": "monospace" },
          "fontSize": { "value": 10 },
          "fill": { "signal": "indexof(selectedApps, '|' + datum.app + '|') >= 0 ? '#e8f3ff' : '#c9d7e5'" },
          "baseline": { "value": "middle" },
          "limit": { "signal": "width - 110" }
        }
      }
    },
    {
      "type": "text",
      "from": { "data": "apps" },
      "encode": {
        "update": {
          "x": { "signal": "width - 30" },
          "y": { "field": "y" },
          "text": { "signal": "format(datum.count, ',')" },
          "font": { "value": "monospace" },
          "fontSize": { "value": 10 },
          "fill": { "signal": "indexof(selectedApps, '|' + datum.app + '|') >= 0 ? '#d9eeff' : '#8ea3b8'" },
          "align": { "value": "right" },
          "baseline": { "value": "middle" }
        }
      }
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": "fit",
  "padding": 8,
  "background": "#000000",
  "signals": [
    {
      "name": "zoom",
      "value": 0.55,
      "on": [
        {
          "events": { "type": "wheel" },
          "update": "clamp(zoom * pow(1.0015, -event.deltaY), 0.55, 2.6)"
        }
      ]
    },
    {
      "name": "panX",
      "value": 0,
      "on": [
        {
          "events": { "type": "wheel" },
          "update": "((panX - (width/2)) * (clamp(zoom * pow(1.0015, -event.deltaY), 0.55, 2.6) / zoom)) + (width/2)"
        },
        {
          "events": {
            "source": "window",
            "type": "mousemove",
            "between": [
              { "source": "view", "type": "mousedown" },
              { "source": "window", "type": "mouseup" }
            ]
          },
          "update": "panX + event.movementX"
        }
      ]
    },
    {
      "name": "panY",
      "value": 0,
      "on": [
        {
          "events": { "type": "wheel" },
          "update": "((panY - (height/2)) * (clamp(zoom * pow(1.0015, -event.deltaY), 0.55, 2.6) / zoom)) + (height/2)"
        },
        {
          "events": {
            "source": "window",
            "type": "mousemove",
            "between": [
              { "source": "view", "type": "mousedown" },
              { "source": "window", "type": "mouseup" }
            ]
          },
          "update": "panY + event.movementY"
        }
      ]
    },
    {
      "name": "selectedNode",
      "value": null,
      "on": [
        {
          "events": "@nodeMark:click",
          "update": "datum && isValid(datum.id) ? (selectedNode && selectedNode.id===datum.id ? null : datum) : selectedNode"
        }
      ]
    },
    {
      "name": "_applyNodeFilter",
      "value": 0,
      "on": [
        {
          "events": "@nodeMark:dblclick",
          "update": "datum && isValid(datum.id) ? kibanaAddFilter((datum.nodeType === 'application' ? {'bool': {'filter': [{'term': {'event.dataset': 'tychon.application'}}, {'term': {'tychon.application.name': toString(datum.id)}}]}} : {'bool': {'filter': [{'term': {'event.dataset': 'tychon.application'}}, {'term': {'host.hostname': toString(datum.id)}}]}})) : 0",
          "force": true
        }
      ]
    },
    {
      "name": "adjPeerIds",
      "update": "isArray(data('adjacency')) ? pluck(data('adjacency'), 'peer') : []"
    },
    {
      "name": "adjPeer2Ids",
      "update": "isArray(data('adjacency2')) ? pluck(data('adjacency2'), 'peer') : []"
    },
    {
      "name": "highlightNodeIdsCsv",
      "update": "selectedNode ? (',' + toString(selectedNode.id) + ',' + join(adjPeerIds, ',') + ',' + join(adjPeer2Ids, ',') + ',') : ''"
    },
    {
      "name": "autoPanX",
      "update": "length(data('layout_center')) > 0 && isFinite(data('layout_center')[0].cx) ? (width * 0.5) - (data('layout_center')[0].cx * zoom) : (width * (1 - zoom) * 0.5)"
    },
    {
      "name": "autoPanY",
      "update": "length(data('layout_center')) > 0 && isFinite(data('layout_center')[0].cy) ? (height * 0.52) - (data('layout_center')[0].cy * zoom) : (height * (1 - zoom) * 0.5)"
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc-applications",
        "body": {
          "size": 0,
          "aggs": {
            "pairs": {
              "filter": {
                "bool": {
                  "must": [
                    { "exists": { "field": "host.hostname" } },
                    { "exists": { "field": "tychon.application.name" } },
                    { "term": { "event.dataset": "tychon.application" } }
                  ]
                }
              },
              "aggs": {
                "links": {
                  "composite": {
                    "size": 500,
                    "sources": [
                      { "src": { "terms": { "field": "host.hostname" } } },
                      { "dst": { "terms": { "field": "tychon.application.name" } } }
                    ]
                  }
                }
              }
            }
          }
        }
      },
      "format": { "property": "aggregations.pairs.links.buckets" },
      "transform": [
        { "type": "formula", "as": "source", "expr": "datum.key.src" },
        { "type": "formula", "as": "target", "expr": "datum.key.dst" },
        { "type": "formula", "as": "count", "expr": "toNumber(datum.doc_count)" },
        { "type": "filter", "expr": "isValid(datum.source) && isValid(datum.target) && datum.source!='' && datum.target!=''" }
      ]
    },
    {
      "name": "nodes",
      "source": "raw",
      "transform": [
        { "type": "fold", "fields": ["source", "target"], "as": ["side", "id"] },
        { "type": "aggregate", "groupby": ["id", "side"], "fields": ["count"], "ops": ["sum"], "as": ["traffic"] },
        { "type": "formula", "as": "nodeType", "expr": "datum.side==='source' ? 'host' : 'application'" }
      ]
    },
    {
      "name": "edges",
      "source": "raw",
      "transform": [
        { "type": "formula", "as": "source", "expr": "toString(datum.source)" },
        { "type": "formula", "as": "target", "expr": "toString(datum.target)" },
        { "type": "formula", "as": "count", "expr": "toNumber(datum.count)" },
        { "type": "filter", "expr": "datum.source != '' && datum.target != ''" }
      ]
    },
    {
      "name": "layout",
      "source": "nodes",
      "transform": [
        {
          "type": "force",
          "iterations": 300,
          "static": true,
          "forces": [
            { "force": "center", "x": { "signal": "width * 0.5" }, "y": { "signal": "height * 0.52" } },
            { "force": "collide", "radius": 20 },
            { "force": "nbody", "strength": -180 },
            { "force": "link", "links": "edges", "id": "id", "distance": 130 }
          ]
        }
      ]
    },
    {
      "name": "layout_center",
      "source": "layout",
      "transform": [
        {
          "type": "aggregate",
          "ops": ["median", "median"],
          "fields": ["x", "y"],
          "as": ["cx", "cy"]
        },
        { "type": "formula", "as": "cx", "expr": "isFinite(datum.cx) ? datum.cx : 0" },
        { "type": "formula", "as": "cy", "expr": "isFinite(datum.cy) ? datum.cy : 0" }
      ]
    },
    {
      "name": "edges_draw",
      "source": "edges",
      "transform": [
        { "type": "formula", "as": "srcId", "expr": "isValid(datum.source) && isValid(datum.source.id) ? toString(datum.source.id) : toString(datum.source)" },
        { "type": "formula", "as": "dstId", "expr": "isValid(datum.target) && isValid(datum.target.id) ? toString(datum.target.id) : toString(datum.target)" },
        { "type": "formula", "as": "sx", "expr": "isValid(datum.source) && isValid(datum.source.x) ? datum.source.x * zoom + autoPanX + panX : null" },
        { "type": "formula", "as": "sy", "expr": "isValid(datum.source) && isValid(datum.source.y) ? datum.source.y * zoom + autoPanY + panY : null" },
        { "type": "formula", "as": "tx", "expr": "isValid(datum.target) && isValid(datum.target.x) ? datum.target.x * zoom + autoPanX + panX : null" },
        { "type": "formula", "as": "ty", "expr": "isValid(datum.target) && isValid(datum.target.y) ? datum.target.y * zoom + autoPanY + panY : null" },
        { "type": "filter", "expr": "isValid(datum.sx) && isValid(datum.sy) && isValid(datum.tx) && isValid(datum.ty)" }
      ]
    },
    {
      "name": "adjacency",
      "source": "edges",
      "transform": [
        { "type": "formula", "as": "srcId", "expr": "isValid(datum.source) && isValid(datum.source.id) ? toString(datum.source.id) : toString(datum.source)" },
        { "type": "formula", "as": "dstId", "expr": "isValid(datum.target) && isValid(datum.target.id) ? toString(datum.target.id) : toString(datum.target)" },
        { "type": "filter", "expr": "selectedNode && (datum.srcId===toString(selectedNode.id) || datum.dstId===toString(selectedNode.id))" },
        { "type": "fold", "fields": ["srcId", "dstId"], "as": ["side", "peer"] },
        { "type": "filter", "expr": "datum.peer !== toString(selectedNode.id)" },
        { "type": "aggregate", "groupby": ["peer"], "fields": ["count"], "ops": ["sum"], "as": ["traffic"] }
      ]
    },
    {
      "name": "adjacency2",
      "source": "edges",
      "transform": [
        { "type": "formula", "as": "srcId", "expr": "isValid(datum.source) && isValid(datum.source.id) ? toString(datum.source.id) : toString(datum.source)" },
        { "type": "formula", "as": "dstId", "expr": "isValid(datum.target) && isValid(datum.target.id) ? toString(datum.target.id) : toString(datum.target)" },
        { "type": "filter", "expr": "selectedNode && (indexof(adjPeerIds, datum.srcId) >= 0 || indexof(adjPeerIds, datum.dstId) >= 0)" },
        { "type": "fold", "fields": ["srcId", "dstId"], "as": ["side", "peer"] },
        { "type": "filter", "expr": "datum.peer !== toString(selectedNode.id) && indexof(adjPeerIds, datum.peer) < 0" },
        { "type": "aggregate", "groupby": ["peer"], "fields": ["count"], "ops": ["sum"], "as": ["traffic"] }
      ]
    }
  ],
  "marks": [
    {
      "type": "rect",
      "encode": {
        "enter": {
          "x": { "value": 0 },
          "y": { "value": 0 },
          "x2": { "signal": "width" },
          "y2": { "signal": "height" },
          "fill": { "value": "#000000" }
        }
      }
    },
    {
      "type": "rule",
      "from": { "data": "edges_draw" },
      "encode": {
        "update": {
          "x": { "field": "sx" },
          "y": { "field": "sy" },
          "x2": { "field": "tx" },
          "y2": { "field": "ty" },
          "stroke": {
            "signal": "!selectedNode ? '#4fc3f7' : ((indexof(highlightNodeIdsCsv, ',' + datum.srcId + ',') >= 0 && indexof(highlightNodeIdsCsv, ',' + datum.dstId + ',') >= 0) ? '#7fe8ff' : '#213240')"
          },
          "strokeOpacity": {
            "signal": "!selectedNode ? 0.42 : ((indexof(highlightNodeIdsCsv, ',' + datum.srcId + ',') >= 0 && indexof(highlightNodeIdsCsv, ',' + datum.dstId + ',') >= 0) ? 0.75 : 0.08)"
          },
          "strokeWidth": { "value": 0.9 }
        }
      }
    },
    {
      "type": "symbol",
      "from": { "data": "layout" },
      "encode": {
        "update": {
          "x": { "signal": "datum.x * zoom + autoPanX + panX" },
          "y": { "signal": "datum.y * zoom + autoPanY + panY" },
          "size": { "value": 980 },
          "fill": { "signal": "datum.nodeType==='application' ? '#3b2b1a' : '#1a2c3b'" },
          "fillOpacity": { "value": 0.9 },
          "stroke": { "signal": "datum.nodeType==='application' ? '#ffd7a2' : '#a9dbff'" },
          "strokeWidth": { "value": 1.2 },
          "opacity": { "signal": "!selectedNode ? 1 : (indexof(highlightNodeIdsCsv, ',' + toString(datum.id) + ',') >= 0 ? 1 : 0.2)" }
        }
      }
    },
    {
      "type": "symbol",
      "name": "nodeMark",
      "from": { "data": "layout" },
      "encode": {
        "enter": {
          "size": { "value": 980 },
          "fill": { "value": "#000000" },
          "fillOpacity": { "value": 0.001 },
          "stroke": { "value": "#000000" },
          "strokeOpacity": { "value": 0.001 },
          "cursor": { "value": "pointer" }
        },
        "update": {
          "x": { "signal": "datum.x * zoom + autoPanX + panX" },
          "y": { "signal": "datum.y * zoom + autoPanY + panY" },
          "size": { "value": 980 }
        }
      }
    },
    {
      "type": "text",
      "from": { "data": "layout" },
      "encode": {
        "update": {
          "x": { "signal": "datum.x * zoom + autoPanX + panX" },
          "y": { "signal": "datum.y * zoom + autoPanY + panY - 14" },
          "text": { "field": "id" },
          "fill": { "signal": "!selectedNode ? '#e0e0e0' : (indexof(highlightNodeIdsCsv, ',' + toString(datum.id) + ',') >= 0 ? '#f2f7ff' : '#4f5f6f')" },
          "font": { "value": "monospace" },
          "fontSize": { "value": 9 },
          "align": { "value": "center" },
          "baseline": { "value": "bottom" }
        }
      }
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Selection details panel for host/application context using dashboard filters.",
  "autosize": "fit",
  "padding": 10,
  "background": "#000000",
  "signals": [
    { "name": "panelW", "update": "width - 20" },
    { "name": "labelX", "value": 26 },
    { "name": "valueX", "update": "width * 0.42" },
    { "name": "row0", "value": 74 },
    { "name": "rowH", "value": 24 }
  ],
  "data": [
    {
      "name": "context",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc*",
        "body": {
          "size": 0,
          "aggs": {
            "host": { "terms": { "field": "observer.hostname", "size": 1 } },
            "app": { "terms": { "field": "tychon.application.name.keyword", "size": 1 } },
            "dst": { "terms": { "field": "server.address", "size": 1 } },
            "proto": { "terms": { "field": "network.protocol", "size": 1 } },
            "tls_ver": { "terms": { "field": "tls.preferred_protocol", "size": 1 } },
            "cipher": { "terms": { "field": "tls.preferred_cipher", "size": 1 } },
            "events": { "value_count": { "field": "@timestamp" } },
            "first_seen": { "min": { "field": "@timestamp" } },
            "last_seen": { "max": { "field": "@timestamp" } }
          }
        }
      },
      "format": { "property": "aggregations" },
      "transform": [
        {
          "type": "formula",
          "as": "host",
          "expr": "datum.host && datum.host.buckets && length(datum.host.buckets)>0 ? datum.host.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "app",
          "expr": "datum.app && datum.app.buckets && length(datum.app.buckets)>0 ? datum.app.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "dst",
          "expr": "datum.dst && datum.dst.buckets && length(datum.dst.buckets)>0 ? datum.dst.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "proto",
          "expr": "datum.proto && datum.proto.buckets && length(datum.proto.buckets)>0 ? datum.proto.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "tlsVer",
          "expr": "datum.tls_ver && datum.tls_ver.buckets && length(datum.tls_ver.buckets)>0 ? datum.tls_ver.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "cipher",
          "expr": "datum.cipher && datum.cipher.buckets && length(datum.cipher.buckets)>0 ? datum.cipher.buckets[0].key : ''"
        },
        { "type": "formula", "as": "events", "expr": "datum.events ? datum.events.value : 0" },
        {
          "type": "formula",
          "as": "firstSeen",
          "expr": "datum.first_seen && isValid(datum.first_seen.value_as_string) ? datum.first_seen.value_as_string : ''"
        },
        {
          "type": "formula",
          "as": "lastSeen",
          "expr": "datum.last_seen && isValid(datum.last_seen.value_as_string) ? datum.last_seen.value_as_string : ''"
        },
        {
          "type": "formula",
          "as": "selectionType",
          "expr": "datum.app != '' ? 'APPLICATION CONTEXT' : (datum.host != '' ? 'HOST CONTEXT' : 'NO SELECTION')"
        },
        {
          "type": "formula",
          "as": "selectionId",
          "expr": "datum.app != '' ? datum.app : (datum.host != '' ? datum.host : 'Select a host/app in the graph')"
        }
      ]
    },
    {
      "name": "rows",
      "source": "context",
      "transform": [
        {
          "type": "project",
          "fields": [
            "selectionType",
            "selectionId",
            "host",
            "app",
            "dst",
            "proto",
            "tlsVer",
            "cipher",
            "events",
            "firstSeen",
            "lastSeen"
          ],
          "as": [
            "selectionType",
            "selectionId",
            "host",
            "app",
            "dst",
            "proto",
            "tlsVer",
            "cipher",
            "events",
            "firstSeen",
            "lastSeen"
          ]
        },
        {
          "type": "formula",
          "as": "kv",
          "expr": "[{k:'Context',v:datum.selectionType},{k:'Selection',v:datum.selectionId},{k:'Source Host',v:datum.host},{k:'Application',v:datum.app},{k:'Destination',v:datum.dst},{k:'Protocol',v:datum.proto},{k:'TLS Version',v:datum.tlsVer},{k:'Cipher',v:datum.cipher},{k:'Event Count',v:format(datum.events, ',')},{k:'First Seen',v:datum.firstSeen},{k:'Last Seen',v:datum.lastSeen}]"
        },
        { "type": "flatten", "fields": ["kv"], "as": ["row"] },
        { "type": "window", "ops": ["row_number"], "as": ["rn"] },
        { "type": "formula", "as": "y", "expr": "row0 + (datum.rn - 1) * rowH" }
      ]
    }
  ],
