{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Selection risk dial aligned to inventory OMB readiness tiers.",
  "autosize": "fit",
  "padding": 10,
  "background": "#000000",
  "signals": [
    { "name": "cx", "update": "width/2" },
    { "name": "cy", "update": "height*0.56" },
    { "name": "r", "update": "min(width, height) * 0.34" }
  ],
  "data": [
    {
      "name": "risk",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc-inventory*",
        "body": {
          "size": 0,
          "aggs": {
            "apps_total": { "cardinality": { "field": "process.executable" } },
            "kex_ready": {
              "filter": { "term": { "omb.kex_tier": "PQC READY" } },
              "aggs": { "u": { "cardinality": { "field": "process.executable" } } }
            },
            "proto_ready": {
              "filter": { "term": { "omb.protocol_tier": "TLS 1.3" } },
              "aggs": { "u": { "cardinality": { "field": "process.executable" } } }
            },
            "sig_ready": {
              "filter": { "term": { "omb.sig_tier": "PQC READY" } },
              "aggs": { "u": { "cardinality": { "field": "process.executable" } } }
            }
          }
        }
      },
      "format": { "property": "aggregations" },
      "transform": [
        { "type": "formula", "as": "n", "expr": "isValid(datum.apps_total) && isValid(datum.apps_total.value) ? max(1, datum.apps_total.value) : 1" },
        { "type": "formula", "as": "kex_ready_n", "expr": "isValid(datum.kex_ready) && isValid(datum.kex_ready.u) && isValid(datum.kex_ready.u.value) ? datum.kex_ready.u.value : 0" },
        { "type": "formula", "as": "proto_ready_n", "expr": "isValid(datum.proto_ready) && isValid(datum.proto_ready.u) && isValid(datum.proto_ready.u.value) ? datum.proto_ready.u.value : 0" },
        { "type": "formula", "as": "sig_ready_n", "expr": "isValid(datum.sig_ready) && isValid(datum.sig_ready.u) && isValid(datum.sig_ready.u.value) ? datum.sig_ready.u.value : 0" },
        { "type": "formula", "as": "p_kex_ready", "expr": "100 * datum.kex_ready_n / datum.n" },
        { "type": "formula", "as": "p_proto_ready", "expr": "100 * datum.proto_ready_n / datum.n" },
        { "type": "formula", "as": "p_sig_ready", "expr": "100 * datum.sig_ready_n / datum.n" },
        { "type": "formula", "as": "readiness", "expr": "clamp(round((datum.p_kex_ready + datum.p_proto_ready + datum.p_sig_ready) / 3), 0, 100)" },
        { "type": "formula", "as": "score", "expr": "clamp(100 - datum.readiness, 0, 100)" },
        { "type": "formula", "as": "tier", "expr": "datum.readiness >= 90 ? 'LOW' : datum.readiness >= 60 ? 'MEDIUM' : 'HIGH'" },
        { "type": "formula", "as": "color", "expr": "datum.readiness >= 90 ? '#22c55e' : datum.readiness >= 60 ? '#f59e0b' : '#ef4444'" },
        { "type": "formula", "as": "angle", "expr": "-3.1415926 + (datum.score/100) * 3.1415926 * 2" }
      ]
    }
  ],
  "marks": [
    {
      "type": "arc",
      "from": {"data": "risk"},
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy"},
        "innerRadius": {"signal": "r-18"}, "outerRadius": {"signal": "r"},
        "startAngle": {"value": -3.1415926}, "endAngle": {"value": 3.1415926},
        "fill": {"value": "#1f2937"}
      }}
    },
    {
      "type": "arc",
      "from": {"data": "risk"},
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy"},
        "innerRadius": {"signal": "r-18"}, "outerRadius": {"signal": "r"},
        "startAngle": {"value": -3.1415926}, "endAngle": {"field": "angle"},
        "fill": {"field": "color"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "risk"},
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy - 6"}, "align": {"value": "center"},
        "text": {"signal": "format(datum.score, 'd') + '/100'"}, "font": {"value": "monospace"},
        "fontSize": {"value": 28}, "fontWeight": {"value": "bold"}, "fill": {"field": "color"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "risk"},
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy + 24"}, "align": {"value": "center"},
        "text": {"signal": "datum.tier + ' RISK'"}, "font": {"value": "monospace"},
        "fontSize": {"value": 12}, "fontWeight": {"value": "bold"}, "fill": {"value": "#cfe3f7"}
      }}
    }
  ]
}
